solutions.naive:
class Solution:
    def reverseBits(self, n: int) -> int:
        bits = format(n & 0xFFFFFFFF, "032b")
        reversed_bits = bits[::-1]
        return int(reversed_bits, 2)

solutions.better:
class Solution:
    def reverseBits(self, n: int) -> int:
        n &= 0xFFFFFFFF
        ans = 0
        for i in range(32):
            if n & (1 << i):
                ans |= 1 << (31 - i)
        return ans

solutions.optimal:
class Solution:
    def reverseBits(self, n: int) -> int:
        n &= 0xFFFFFFFF
        ans = 0
        for _ in range(32):
            ans = (ans << 1) | (n & 1)
            n >>= 1
        return ans & 0xFFFFFFFF

